DELETE FROM oauth_access_token WHERE user_name = #{username} AND client_id = #{clientId};
DELETE FROM oauth_client_details WHERE client_id = #{clientId};
DELETE FROM oauth_refresh_token WHERE token_id = #{tokenId};
